def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_d = opp.count('D')
    my_d = my.count('D')

    if opp_d == 0:
        if n >= 97:
            if my_d == 0:
                return 'D'
            if my[-1] == 'D':
                return 'C'
            return 'D'
        return 'C'

    my_last = my[-1]
    opp_last = opp[-1]

    recent = history[-10:] if n >= 10 else history
    opp_coops = sum(1 for _, o in recent if o == 'C')
    total = len(recent)
    coop_rate = opp_coops / total if total > 0 else 1.0

    if n >= 4:
        last4 = history[-4:]
        if all(a == 'D' and b == 'D' for a, b in last4):
            return 'C'

    if opp_last == 'D':
        if my_last == 'C':
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        if my_last == 'D':
            if rng.random() < 0.25:
                return 'C'
            return 'D'
    else:
        if my_last == 'D' and coop_rate > 0.4:
            return 'C'
        if coop_rate > 0.6:
            return 'C'
        if coop_rate > 0.35:
            return 'C' if rng.random() < 0.7 else 'D'
        return 'D' if rng.random() < 0.6 else 'C'

    return 'C'
